// PORT-ESCALATION(raw-ptr-skeleton-no-world-handle): indexes `g_entities`,
// calls `trap_InPVS`/`trap_Trace`; also a fn-pointer write
// (`think = G_FreeEntity`).
/// Raven `G_PortalifyEntities`.
///
/// Source: `oracle/oracle/codemp/game/g_misc.c:638-667`
pub fn G_PortalifyEntities(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    use mp_qshared::shared::limits::{ENTITYNUM_NONE, ENTITYNUM_WORLD};
    unsafe {
        let mut i: usize = 0;
        while i < mp_qshared::shared::MAX_GENTITIES {
            let scan = &mut (*ctx.world).entities[i] as *mut gentity_t;
            if (*scan).inuse != 0
                && (*scan).s.number != (*ent).s.number
                && trap::InPVS(
                    ctx.engine,
                    GInPvsArgs::new(&(*ent).s.origin as *const vec3_t, &(*scan).r.currentOrigin as *const vec3_t),
                ) != 0
            {
                let mut tr: trace_t = core::mem::zeroed();
                trap::Trace(
                    ctx.engine,
                    GTraceArgs::new(
                        &mut tr as *mut trace_t,
                        &(*ent).s.origin as *const vec3_t,
                        &vec3_origin as *const vec3_t,
                        &vec3_origin as *const vec3_t,
                        &(*scan).r.currentOrigin as *const vec3_t,
                        (*ent).s.number,
                        mp_qshared::shared::surface_flags::CONTENTS_SOLID,
                    ),
                );
                if tr.fraction == 1.0
                    || (tr.entityNum == (*scan).s.number
                        && tr.entityNum != ENTITYNUM_NONE
                        && tr.entityNum != ENTITYNUM_WORLD)
                {
                    if (*scan).client.is_null() || (*scan).s.eType == entity_type_t::ET_NPC as c_int {
                        (*scan).s.isPortalEnt = qtrue;
                    }
                }
            }
            i += 1;
        }

        (*ent).think = Some(EntThink::G_FreeEntity);
        (*ent).nextthink = (*ctx.world).level.time;
    }
}

