/// Raven `maglock_die`.
///
/// Unlocks our door if we're the last lock pointed at the door, then fires
/// this maglock's targets. `WP_Explode` was already dead code upstream
/// (`//rwwFIXMEFIXME - weap expl func`).
/// Source: `oracle/oracle/codemp/game/g_misc.c:2623-2640`
pub fn maglock_die(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    inflictor: *mut gentity_t,
    attacker: *mut gentity_t,
    damage: c_int,
    r#mod: c_int,
) {
    use crate::entity::flags::FL_INACTIVE;
    unsafe {
        if !(*self_).activator.is_none() {
            let door = (*self_).activator;
            (*door).lockCount -= 1;
            if (*door).lockCount == 0 {
                (*door).flags &= !FL_INACTIVE;
            }
        }
        G_UseTargets(ctx, self_, attacker);
    }
}

